$(document).ready(function () {

  // all reviewed

  //  Hashtags, plans, coupons, Alerts
  var coupon_type_value  = $('#coupon-type-value');
  var coupon_type = $('#coupon-type');
  var msg_emoji_box, emoji_area_text_length;

  // emojionearea
  if ($("#hashtag-response-textarea").length) {
    var msg_emoji_box =  $('#hashtag-response-textarea').emojioneArea({
      pickerPosition: "bottom"
    });

    $(window).load(function(){
      $('.emojionearea-editor').counter({
        count: "down",
        goal: 300,
        target: '#char-count',
        msg: 'character(s)'
      });
    });

    msg_emoji_box[0].emojioneArea.on('change', function(e) {
      $('#new_hashtag').formValidation('resetField', 'hashtag[response]');
    });
  };

  // no spaces
  $('#coupon-name').on('input', function() { this.value = this.value.replace(/\s+/g, ''); });
  $('#hashtag_tag').on('input', function() { $(this).val('#'+ this.value.replace(/[^a-z0-9]/gi,'')); });

  // Positive integer only
  $('#duration-in-months, #max-redemptions, #subscription_quantity').on('input', function(){
    this.value = UtilFunctions.positive_integer_only(this.value);
  });

  function positive_integer_less_than_100(v) {
    if (!(/^(\d+)$/.test(v))) return '';
    else {
      if (v.match(/^[1-9]\d*$/) && parseInt(v) < 101) return v;
      else return v.slice(0, -1);
    }
  };

  function decimal_with_up_to_two_places(v) {
    if (!(/^(\d+)(\.)?(\d+)?$/.test(v))) return '';
    else {
      if (v.slice(-1) == '.' && (v.match(/[.]/g) || []).length == 1 && v.length > 1) return v;
      // http://stackoverflow.com/questions/30606348/check-if-a-given-value-is-a-positive-number-or-float-with-maximum-two-decimal-pl
      // http://stackoverflow.com/questions/25053605/regex-to-allow-only-a-single-dot-in-a-textbox
      else if (v.match(/^\d+(.\d{1,2})?$/)) return v;
      else return parseFloat(v).toFixed(2);
    }
  };

  // delete hashtag button
  $('#delete-hashtag').click(function(e) {
    var selectedElement = CheckedItem.get();
    if (selectedElement == false) {
      FlashHandler.setFlashMessage('Select a hashtag to delete', 'error');
    } else {
      var id = '#hashtag-delete-' + selectedElement.data('obj-id');
      FlashHandler.setConfirmationDialog(id, 'Are you sure you want to delete this hashtag?', 'Delete');
    };
    return false;
  });

  // deactivate hashtag button 
  $('#deactivate-hashtag').click(function() {
    if (!CheckedItem.get()) {
      FlashHandler.setFlashMessage('Select a hashtag to change status', 'error');
    } else {
      FlashHandler.setConfirmationDialog('#deactivate-hashtag', 'Are you sure you want to change hashtag status?', 'Change');
    };
    return false;
  });

  // decimal with two places
  $('#hashtag_amount, #amount_1 ,#Plan-Amount, #charge-amount, #Add-Funds').on('input', function(e) {
    $(this).val(function(_, v) {
      return decimal_with_up_to_two_places(v);
    });
  });

  coupon_type_value.on('input', function(){
    var v = this.value;
    this.value = (coupon_type.val() == 'amount_off') ? decimal_with_up_to_two_places(v) : positive_integer_less_than_100(v);
  });

  coupon_type.on('change', function() {
    var name_value, placeholder_value;

    if (this.value == 'amount_off') {
      name_value = "coupon[amount_off]";
      placeholder_value = "Amount";
      $('#couponForm').formValidation('resetField', 'coupon[percent_off]');
    } else {
      name_value = "coupon[percent_off]";
      placeholder_value = "Percentage";
      $('#couponForm').formValidation('resetField', 'coupon[amount_off]');
    }

    coupon_type_value.val('').attr('name', name_value);
    coupon_type_value.attr('placeholder', placeholder_value);
  });

  // validate hashtag form
  $('#new_hashtag')
  .formValidation({
    framework: 'bootstrap',
    excluded: ':disabled',
    live: 'disabled',
    fields: {
      'hashtag[name]': {
        verbose: false,
        threshold: 2,
        validators: {
          notEmpty: {
            message: 'Name is required'
           },
          remote: {
            message: 'Hashtag name is already taken.',
            url: '/v1/hashtags/check_hashtag_name',
            type: 'GET',
            delay: 1500     // Send Ajax request every 1.5 seconds
          }
        },
      },
      'hashtag[tag]': {
        validators: {
          notEmpty: {
            message: 'Tag  is required'
          },
          stringLength: {
            message: "Tag should be less than 30 characters",
            max: 30
          },
          callback: {
            callback: function (value, validator, $field) {
              if (/#(?![0-9]+\b)([a-zA-Z0-9]{1,30})/.test(value)) {
                return {
                  valid: true,
                  //message: ''
                }
              } else {
                return {
                  valid: false,
                  message: "Invalid tag format"
                }
              }
            }
          }
        },
      },
      'hashtag[amount]': {
        validators: {
          callback: {
            callback: function (value, validator, $field) {
              if ($('#hashtag_tag_type').val() != 0) {
                if ($('#hashtag_amount').val().length > 0) {
                  return {
                    valid: true,
                    //message: 'Valid number'
                  }
                } else {
                  return {
                    valid: false,
                    message: "amount is required"
                  }
                }
              } else {
                return { valid: true }
              }
            }
          }
        }
      },
      'hashtag[response]': {
        validators: {
          notEmpty: {
            message: ' '
          }
        }
      }
    }
  });

  // if hashtag isn't for payment, hide payment settings
  $('#hashtag_tag_type').change(function(){
    if (this.value == '0') {
      $('.hashtag-payment-settings').slideUp(200);
      $('#interval-settings').hide();
      $('#hashtag_amount').val('');
    } else {
      if (this.value == '1') {
        $('#interval-settings').hide();
      } else {
        $('#interval-settings').show();
      }
      $('.hashtag-payment-settings').slideDown(200);
    }
    $('#new_hashtag').formValidation('revalidateField', 'hashtag[amount]');
  }).change();
});
$(document).ready(function() {
  // additional plan code in hashtags_plans_coupons_alerts js file

  var current_plan_name, save_icon_parent,
      save_icon_grandparent, plan_name_input;

  // validate plan form
  if ($('#planForm').length > 0) {
    $('#planForm').formValidation({
        framework: 'bootstrap',
        live: 'disabled',
        // List of fields and their validation rules
        fields: {
          'plan[name]': {
            validators: {
              notEmpty: {
                message: 'Name is required'
              },
              remote: {
                message: 'This Plan name has already been used.',
                url: '/v1/plans/check_plan_name',
                type: 'POST'
              }
            }
          },
          'plan[amount]': {
            validators: {
              notEmpty: {
                message: 'Amount  is required'
              }
            }
          }
        }
      })
      .on('success.validator.fv', function(e, data) {
        data.element // Get the field element
          .closest('.form-group') // Get the field parent
          .removeClass('has-warning')
          .addClass('has-success')
      })
      .on('success.form.fv', function(e, data) {
          e.preventDefault();
          $('#create-plan').attr("disabled", true).val("Please wait...");
          addPlan();
      })
      .on('err.validator.fv', function(e) {
        $('.help-block').hide();
      });
  }

  $('#Plan-name').on("input", function() {
    $('#planForm').formValidation('revalidateField', 'plan[name]');
  });

  // create plan using modal through api call
  function addPlan(){
    $.ajax({
        url: "/v1/plans.json",
        beforeSend: function(xhr) {
          xhr.setRequestHeader('X-CSRF-Token', $('meta[name="csrf-token"]').attr('content'))
        },
        type: "POST",
        data: $('#planForm').serialize(),
        dataType: "json"
      })
      .done(function(data, textStatus, jqXHR) {
        FlashHandler.setFlashMessage(data.response, 'notice');
        $('#planForm')[0].reset();
        $('#planForm').data('formValidation').resetForm();
        $('.update-close-modals').click();
      })
      .fail(function(data, textStatus, errorThrown) {
        FlashHandler.setFlashMessage(JSON.parse(data.responseText).response, 'error');
        $('#create-plan').attr("disabled", false).val("Create Plan");
      })
    .always(function(data, textStatus, response) {
        $('#create-plan').attr("disabled", false).val("Create Plan");
      });
  };

  /**
    We're defining the event on the `body` element, because we know the `body` is not going away.
    Second argument makes sure the callback only fires when the `click` event happens only on elements marked as `data-editable`
  */
  $('body').on('click', '.plan-name-edit-icon', function(e) {
    e.stopImmediatePropagation();
    if ($('.plan-name.editable.open').length > 0) {
      $('.plan-name.editable.open').parent().find('.cancel-edit-plan').click()
    }
    var parent = $(this).parent();
    parent.css('display','none');
    parent = parent.parent();
    parent.find(".plan-name-save-span").css('display','block');
    var $el = parent.find('.plan-name');
    current_plan_name = $el.text();
    var $input = $('<input class="plan-name editable open text-field w-input" placeholder="Plan name" />').val( current_plan_name );
    $el.replaceWith( $input );
    $input.focus();
  });

  $('body').on('click', '.plan-name-save-icon, .cancel-edit-plan', function(e) {
    e.stopImmediatePropagation();
    save_icon_parent = $(this).parent();
    save_icon_grandparent = save_icon_parent.parent();
    plan_name_input = save_icon_grandparent.find('.plan-name');
    cancel_edit = 'cancel-edit cancel-edit-plan save-editable-field'

    if ((current_plan_name == plan_name_input.val()) || ($(this).attr('class') === cancel_edit)) {
      plan_name = current_plan_name
      revert_to_text();
    } else {
      plan_name = plan_name_input.val();
      this.disabled = true;
      updatePlanName(this);
    }
  });

  function revert_to_text() {
    save_icon_parent.css('display','none');
    save_icon_grandparent.find(".plan-name-edit-span").css('display','block');
    var $span = $('<span class="editable-field-text settings-row-text plan-name" />').text( plan_name );
    plan_name_input.replaceWith( $span );
  }

  function updatePlanName(plan_save_icon) {
    $.ajax({
      url: "/v1/plans/" + save_icon_parent.data('plan-id') + ".json",
      beforeSend: function(xhr) { xhr.setRequestHeader('X-CSRF-Token', $('meta[name="csrf-token"]').attr('content')); },
      type: "PATCH",
      data: { plan: { name: plan_name_input.val() }} ,
      dataType: "json"
    })
      .done(function(data, textStatus, jqXHR) {
        FlashHandler.setFlashMessage(data.response, 'notice');
        revert_to_text();
      })
      .fail(function(data, textStatus, errorThrown) {
        FlashHandler.setFlashMessage(JSON.parse(data.responseText).response, 'error');
      })
      .always(function(data, textStatus, response) {
        plan_save_icon.disabled = false;
      });
  };

});

