messagingApp.directive('whenScrolledUp', ['$timeout', function($timeout) {
  return function(scope, elm, attr) {
    var raw = elm[0];   
    var debounced = _.debounce(function() {
      console.log('debounced')
      if (!scope.retrieving_messages_for_scroll && raw.scrollTop <= 0) {
        console.log('retrieving')
        scope.retrieving_messages_for_scroll = true;
        var sh = raw.scrollHeight;
        scope.$apply(attr.whenScrolledUp).then(function() {
          $timeout(function() {
            raw.scrollTop = raw.scrollHeight - sh;
            scope.retrieving_messages_for_scroll = false;
            $('.dashboard-body').perfectScrollbar('update');
            console.log('scroll complete');
          });
        });
      }
    }, 350);

    elm.bind('scroll', debounced);
  };
}]);

messagingApp.directive('whenScrolledDown', ['$timeout', function($timeout) {
  return function(scope, elm, attr) {
    var raw = elm[0];        
    elm.bind('scroll', _.throttle(function() {
      if (hasScrollReachedBottom(raw))
        scope.$apply(attr.whenScrolledDown).then(function() {
          $timeout(function() {
            $('#conversation-list-wrapper').perfectScrollbar('update');
          });
        });
    }, 350));
  };
}]);

messagingApp.directive("mySrc", function() {
  return {
    link: function(scope, element, attrs) {
      var img, loadImage;
      img = null;

      loadImage = function() {

        element[0].src = "/assets/Relay-Image-Placeholder-d4d86a697b4c4a0386df1404e02c1d9c5330a5b0a3a043695e2ee4e3911adced.png";

        img = new Image();
        img.src = attrs.mySrc;

        img.onload = function() {
          element.hide();
          element[0].src = attrs.mySrc;
          element.fadeIn('slow');
        };
      };

      loadImage();
    }
  };
});

var hasScrollReachedBottom = function(element) {
  // not perfect
  //return element.scrollTop + $(element).innerHeight() >= element.scrollHeight;
  return element.scrollTop <= element.scrollHeight - element.clientHeight;
};

messagingApp.directive('onFinishRender', function ($timeout) {
  return {
    restrict: 'A',
    link: function (scope, element, attr) {
      var raw = element[0];
      if (scope.$last === true) {
        if (hasScrollReachedBottom(raw.parentElement)) {
          $timeout(function() {
            console.log(raw.parentElement)
            console.log(raw.parentElement.scrollHeight)
            raw.parentElement.scrollTop = raw.parentElement.scrollHeight;
            $('.dashboard-body').perfectScrollbar('update');
          });
        }
      }
    }
  }
});

