var PhoneNumberFormatter = new function() {

  var input = "";

  this.init = function(selector) {
    input = $(selector)
    input.intlTelInput({
      nationalMode: true,
      initialCountry: 'auto',
      geoIpLookup: function(callback) {
        $.get(UtilFunctions.get_ipinfo_url(), function() {}, "jsonp").always(function(resp) {
          var countryCode = (resp && resp.country) ? resp.country : "";
          callback(countryCode);
        });
      },
      utilsScript: "/assets/utils-3479360dd26c398df3573e6e503b7927ab9b0507c75ba28852a527fe0b31e2af.js" // just for formatting/placeholders etc
    });
  }

  this.isValid = function() {
    // I think it throws an error if it can't determine country code
    try { return input.intlTelInput("isValidNumber"); }
    catch(err) { return false; }
  };

  this.getNumber = function() {
    return input.intlTelInput("getNumber");
  };

  this.getNationalFormatNumber = function() {
    return input.intlTelInput("getNumber", intlTelInputUtils.numberFormat.NATIONAL);
  };

  this.set_phone_number = function(with_plus) {
    var number = PhoneNumberFormatter.getNumber();
    console.log(input.intlTelInput("getNumber", intlTelInputUtils.numberFormat.NATIONAL))
    if (!with_plus && number) number = number.replace("+", '');
    if (number) $('#phone_number').val(number);
  }

};


$(document).ready(function () {
  // if presetting field, you must set the value to phone_number field before calling the code below
  PhoneNumberFormatter.init('#phone');
  var number = $('#phone_number').val();
  if (number) $("#phone").intlTelInput("setNumber", "+" + number);

  $('#phone').on('focus', function() {
    $(this).removeClass('red-border');
    this.value = UtilFunctions.positive_integer_only(this.value);
  });

});
$(document).ready(function () {  

  //get_ip_info(save_referrer_uid);
  
  function get_ip_info(function_to_run) { 
    $.getJSON(UtilFunctions.get_ipinfo_url(), function(data) { 
      function_to_run(data);
    });
  };
  
  function save_referrer_uid(data) {
    var params = PageParameter.get_params();
    if (params['referrer_uid']) {
      var hash = { referrer: { referrer_uid: params["referrer_uid"] } };

      $.each(data, function( key, value) {
        hash.referrer[key] = value;
      });

      $.ajax({
        url: "/homepage_referrer",
        beforeSend: function(xhr) {
          xhr.setRequestHeader('X-CSRF-Token', $('meta[name="csrf-token"]').attr('content'))
        },
        type: 'POST',
        data: hash
      }).done(function() { console.log('done') });
    };
  };
  
});
