var CardHandler = new function() {
  
  // http://www.phpied.com/3-ways-to-define-a-javascript-class/
  var form_submission_function, form_btn_text;
  var form_btn, form_selector;

  // tokenize card details
  this.submit_to_stripe = function(form_id, btn_id, function_for_submission) {
    form_selector = form_id;
    form_submission_function = function_for_submission;
    var y = UtilFunctions.get_card_expiry_date_data();

    form_btn = $(btn_id);
    form_btn_text = form_btn.val();        // So the button can be reset on fail
    console.log(form_btn_text)
    form_btn.attr("disabled", true).val("Please wait...");

    Stripe.card.createToken({
      name: $('#cc-name').val(),
      number: $('#cc-number').val(),
      exp_month: y.month,
      exp_year: y.year,
      cvc: $('#cc-csc').val()
    }, stripeResponseHandler);
  };

  function stripeResponseHandler(status, response) {
    if (response.error) {
      FlashHandler.setFlashMessage(response.error.message, 'error');
      form_btn.attr("disabled", false).val(form_btn_text);
      show_stripe_error_field(response.error.param);
    } else {
      $('#cc-number').val(response.card.last4);
      $('#cc-ex-month').val(response.card.exp_month);
      $('#cc-ex-year').val(response.card.exp_year);
      $('#cc-uri').val(response.id);
      $('#cc-livemode').val(response.livemode);
      $('#cc-id').val(response.card.id);
      $('#cc-type').val(response.card.brand);
      form_submission_function();
    }
  }

  function show_stripe_error_field(param) {
    if (param == "cvc") {
      $(form_selector).data('formValidation').updateStatus('cc-csc', 'INVALID', 'callback');
    } else if (param == "exp_year" || param == "exp_month") {
      $(form_selector).data('formValidation').updateStatus('cc-exp', 'INVALID', 'callback');
    } else if (param == "number") {
      $(form_selector).data('formValidation').updateStatus('cc-number', 'INVALID', 'callback');
    } else {
      $(form_selector).data('formValidation').resetForm();
    }
  }

}
;
$(document).ready(function () {

  var cc_form_btn = '#cc-submit', cc_form_id = "#cc-form";

  $('input#cc-number').payment('formatCardNumber');
  $('input#cc-exp').payment('formatCardExpiry');
  $('input#cc-csc').payment('formatCardCVC');

  $(cc_form_id).formValidation({
    framework: 'bootstrap',
    live: 'disabled',
    err: {
      container: function($field, validator) {
        
        /*
        if($field.attr("id") == "cc-exp" ){
          return '#cardDate';
        }

        if($field.attr("id") == "cc-csc"){
          return '#cardCvv';
        }
        */

        return $field.parent().find('.messageContainer').show();
      }
    },
    fields: {
      'cc-name': {
        selector: '#cc-name',
        validators: {
          notEmpty: {
            message: 'Card name is required'
          }
        }
      },
      'cc-number': {
        selector: '#cc-number',
        validators: {
          callback: {
            callback: function (value, validator, $field) {
              if ($.payment.validateCardNumber(value)) {
                return {
                  valid: true,    // or false
                  message: 'Valid number'
                }
              } else {
                return {
                  valid: false,    // or false
                  message: 'Enter a valid number'
                }
              }
            }
          }
        }
      },
      'cc-exp': {
        selector: '#cc-exp',
        validators: {
          callback: {
            callback: function (value, validator, $field) {
              var y = UtilFunctions.get_card_expiry_date_data();
              if ($.payment.validateCardExpiry(y.month, y.year)) {
                return {
                  valid: true,    // or false
                  message: 'Valid date'
                }
              } else {
                return {
                  valid: false,    
                  message: ''      // Enter a valid date'
                }
              }
            }
          }
        }
      },
      'cc-csc': {
        selector: '#cc-csc',
        validators: {
          callback: {
            callback: function (value, validator, $field) {
              if ($.payment.validateCardCVC(value)) {
                return {
                  valid: true,    // or false
                  message: 'Valid csc'
                }
              } else {
                return {
                  valid: false,    
                  message: ''      // Enter a valid csc'
                }
              }
            }
          }
        }
      }
    }
  })
  .on('err.field.fv', function(e, data) {
    // $(e.target)  --> The field element
    // data.fv      --> The FormValidation instance
    // data.field   --> The field name
    // data.element --> The field element

    // Hide the messages
    // data.element
    //   .data('fv.messages')
    //   .find('.help-block[data-fv-for="' + data.field + '"]').hide();
  })
  .on('success.form.fv', function(e, data) {
    e.preventDefault();
    CardHandler.submit_to_stripe(cc_form_id, cc_form_btn, submit_cc_form);
  });

  function submit_cc_form() { $(cc_form_id).data('formValidation').defaultSubmit(); };

  // Simply populates credit card and bank account fields with test data
  /*
  $('#populate').click(function () {
    $(this).attr("disabled", true);

    $('#cc-name').val('John Doe');
    $('#cc-number').val('<redacted_phone_number>');
    $('#cc-ex-month').val('12');
    $('#cc-ex-year').val('2020');
    $('#ex-csc').val('123');
  });
  */
});
var PriceSlider = new function() {

  var pricingSlider, priceValueSpan, amount, selection; //currentAmount,
  var plans = { 1: { amt: 50, min: 250, max: 250, smsCount: 1000  },
                2: { amt: 150, min: 251, max: 1000, smsCount: 3000  },
                3: { amt: 350, min: 1001, max: 5000, smsCount: 7000  },
                4: { amt: 700, min: 5001, max: 5050, smsCount: 15000  }
              };

  var keys = Object.keys(plans);

  this.bind_slider = function() {
    // show slider on merchant credit card info update form, show slider on pricing page load
    if ($('#pricing-range').length) {
      pricingSlider = document.getElementById('pricing-range');
      priceValueSpan = document.getElementById('price-value');
      $('.range-bar').remove();
      //currentAmount = (pricingSlider) ? pricingSlider.attributes.amountValue.value : 0;
      if (pricingSlider) {
        var slider = new Powerange(pricingSlider, {
          callback: displayValue, min: 250, max: 5050,
          start: 250, step: 50, vertical: false, hideRange: true
        });
      };
    };
  };

  function displayValue() {
    selection = plan_range(pricingSlider.value);

    // also used by the credit_card_form_js to skip validation
    $('#plan_id').val(selection[0]);
    priceValueSpan.innerHTML = selection[1];

    // for add a subscription page
    if ($('#page_params').val() == 'add_subscription') {
      if (pricingSlider.value <= 100) {
        $('#free-account-label').slideDown(300);
        $('#cc-submit').val('Get Started');
      } else {
        $('#free-account-label').slideUp(300);
        $('#cc-submit').val('Start 14-day Trial');
      };
    };

    /*
    # LEAVE THIS FOR LATER
    //only for subscription setting page
    if ($('#change_subscription_plan')[0]) {
      amount = plan_range(parseInt(pricingSlider.value))[2];
      submitValue = (amount > currentAmount) ?
        'Upgrade Subscription' :
        (amount < currentAmount) ? 'Downgrade Subscription' : 'Subscription';
      (submitValue === 'Subscription') ? $('#change_subscription_plan').hide() : $('#change_subscription_plan').val(submitValue).show();
      $('#pricing-range').val(plan_range(pricingSlider.value)[0]);
    } else {
      $('#select_plan').attr('href', '/users/sign_up?signup_plan=' + plan_range((pricingSlider.value)[0]));
    }
    */
  };

  function plan_range(customerCount) {
    for(var i = 0, len = keys.length; i < len; i++) {
      if (customerCount >= plans[keys[i]].min && customerCount <= plans[keys[i]].max) {
        return [keys[i], planInfo(plans[keys[i]].amt, plans[keys[i]].smsCount)];
      };
    };
  };

  function planInfo(amount, smsCount) {
    if (amount == 700) {
      $('.pricing-table-button').text('Get Started').attr('href', "https://test.withrelay.com/users/sign_up");
      return '<div class="customer-count-text">\
        <span class="customer-count-text-alt">Unlimited tickets</span></div>\
        <div class="price-table underline-div"></div>\
        <span class="customer-count-text-alt">15,000 SMS + Premium support included</span></div>\
        <h1 class="plan-amount plan-amount-margin">$'+ amount +'/month</h1>';
    } else {
      $('.pricing-table-button').text('Get Started').attr('href', "https://test.withrelay.com/users/sign_up");
      return '<div class="customer-count-text">\
        <strong>'+ parseInt(pricingSlider.value).toLocaleString('en-US') +'</strong>\
        <span class="customer-count-text-alt">tickets</span></div>\
        <div class="price-table underline-div"></div>\
        <span class="customer-count-text-alt">'+ smsCount +' SMS included</span></div>\
        <h1 class="plan-amount plan-amount-margin">$'+ amount +'/month</h1>';
    };
  };

};

